contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        uint totalBefore = address(c).balance + address(this).balance;
        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint totalAfter = address(c).balance + address(this).balance;
        assert(totalAfter == totalBefore);
    }

    receive() external payable {}
}

